ValidationRule.errorConditionFormula:
AND(
RecordType.DeveloperName != 'NA_Quality', OR( ISPICKVAL( Priority , 'Medium') , ISPICKVAL( Priority , 'High'), ISPICKVAL( Priority , 'Very High') ), ISPICKVAL(Country_Code__c,'US'), AND( Account.PersonEmail = null, OR( Account.Primary_Phone__c = null, CONTAINS("na:NA:nA:Na", Account.Primary_Phone__c ) ) ), NOT( AND(ISCHANGED(OwnerId),LEFT(PRIORVALUE(OwnerId),3) ='00G') ),$User.FirstName !='System'
)
